import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.1C62pOns.js";const n="/pro-agent-hub-installer/capturas/pt/fontes-detalhe.png",r="/pro-agent-hub-installer/capturas/pt/conhecimento-detalhe.png",h=JSON.parse('{"title":"Conhecimento e fontes de dados","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/conhecimento.md","filePath":"pt/interface/conhecimento.md","lastUpdated":1787856241000}'),d={name:"pt/interface/conhecimento.md"};function c(i,e,m,p,l,u){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="conhecimento-e-fontes-de-dados" tabindex="-1">Conhecimento e fontes de dados <a class="header-anchor" href="#conhecimento-e-fontes-de-dados" aria-label="Permalink to &quot;Conhecimento e fontes de dados&quot;">​</a></h1><p>Um agente sabe o que o modelo aprendeu, e mais nada. <strong>Conhecimento</strong> é como se dá a ele o que a sua empresa sabe.</p><p>São duas peças, e a ordem importa: a <strong>fonte de dados</strong> diz de onde o conteúdo vem; o <strong>conhecimento</strong> transforma esse conteúdo em vetores que o agente consulta.</p><h2 id="fontes-de-dados" tabindex="-1">Fontes de dados <a class="header-anchor" href="#fontes-de-dados" aria-label="Permalink to &quot;Fontes de dados&quot;">​</a></h2><p><img src="'+n+'" alt="fontes-detalhe"></p><p>Há três tipos, e a tela muda conforme o escolhido:</p><p><strong>Banco de dados (SQL).</strong> Uma conexão cadastrada mais uma consulta. Cada linha do resultado vira um documento.</p><p><strong>Pasta de arquivos.</strong> Um diretório do servidor, opcionalmente recursivo, com filtro por extensão. Lê <code>pdf</code>, <code>docx</code>, <code>txt</code>, <code>csv</code>, entre outros.</p><p><strong>Site (web scraping).</strong> Uma URL e <strong>seletores CSS</strong> que dizem qual pedaço da página é qual campo. Cabeçalhos HTTP são opcionais — o <code>User-Agent</code> já vem preenchido, porque sem ele muitos sites recusam a conexão.</p><div class="tip custom-block"><p class="custom-block-title">Não sabe os seletores?</p><p>O botão <strong>Sugerir</strong> aciona o Pegasus: ele busca o HTML real da página e propõe os seletores. É o passo que ninguém consegue adivinhar sem abrir o inspetor do navegador. Exige o Pegasus habilitado em Configurações.</p></div><div class="warning custom-block"><p class="custom-block-title">Páginas que montam o conteúdo em JavaScript ficam de fora</p><p>A captura lê o HTML servido, sem navegador. Se o conteúdo só aparece depois que o JavaScript roda, os seletores não acham nada. É a troca aceita para não carregar um Chromium dentro do container.</p></div><p>A captura tem tetos próprios — tempo total, tamanho do corpo, número de redirecionamentos e 5.000 linhas. Um site é fonte de terceiro: sem teto, uma página lenta ou enorme prenderia o processo.</p><p><strong>Testar</strong> executa a coleta e mostra o que veio, sem gravar nada. Use antes de vincular a um conhecimento.</p><h2 id="conhecimento" tabindex="-1">Conhecimento <a class="header-anchor" href="#conhecimento" aria-label="Permalink to &quot;Conhecimento&quot;">​</a></h2><p><img src="'+r+'" alt="conhecimento-detalhe"></p><p>Um conhecimento aponta para uma fonte de dados e para um <strong>modelo de embedding</strong>, e produz uma coleção de vetores.</p><h3 id="aba-processamento" tabindex="-1">Aba Processamento <a class="header-anchor" href="#aba-processamento" aria-label="Permalink to &quot;Aba Processamento&quot;">​</a></h3><p>Aqui ficam os parâmetros da vetorização:</p><ul><li><strong>Tamanho e sobreposição do bloco</strong> — documentos maiores que o bloco são divididos; a sobreposição evita cortar uma frase ao meio entre dois blocos.</li><li><strong>Tamanho do lote</strong> — quantos documentos vão por vez ao modelo de embedding.</li><li><strong>Máximo de resultados na busca</strong> — quantos trechos o agente recebe por pergunta.</li><li><strong>Expressão cron</strong> — para revetorizar sozinho, de tempos em tempos.</li></ul><p>E três campos de código Python, que valem para a fonte <strong>SQL</strong>:</p><ul><li><strong>Declaração do pipeline</strong> — roda uma vez, antes da ingestão. É onde ficam <code>import</code>, funções auxiliares e acumuladores.</li><li><strong>Conteúdo do documento</strong> — uma expressão que devolve o texto a vetorizar.</li><li><strong>Metadados do documento</strong> — uma expressão que devolve um dicionário.</li></ul><div class="warning custom-block"><p class="custom-block-title">Essas expressões rodam em escopo vazio</p><p>Nenhuma função da plataforma existe ali. O que você tem é <code>row</code>, a linha corrente da consulta, e o que você mesmo definiu na Declaração do pipeline. Ver <a href="/pro-agent-hub-installer/pt/funcoes/conhecimento_pipeline">Conhecimento — expressões do pipeline</a>.</p></div><h3 id="carga-completa" tabindex="-1">Carga completa <a class="header-anchor" href="#carga-completa" aria-label="Permalink to &quot;Carga completa&quot;">​</a></h3><p>A recarga completa <strong>apaga a coleção e a recria</strong>. É o que você quer quando trocou o modelo de embedding (a dimensão muda) ou quando registros foram excluídos na origem e os vetores antigos ficaram para trás. Uma carga normal apenas acrescenta o que mudou.</p>',24)])])}const f=o(d,[["render",c]]);export{h as __pageData,f as default};
